// JSCC DEV Drive Bridge v1: validate the envelope, never interpret it as shell.
export const SCHEMA_VERSION = 1;
export const DEV_PROJECT = 'jscc-dev';
export const BASELINE_SHA = '25a046fffdeccc8c5f877a8c8cac01110f3c7324';
const OPS = Object.freeze({
  bridge_smoke_test: Object.freeze({
    executable: 'node', argv: Object.freeze(['--test', 'drive-bridge/bridge-contract.test.mjs']),
    effect: 'read_and_test_only',
  }),
});
const EXPECTED_KEYS = Object.freeze(['schema_version','job_id','project','environment','operation','baseline_sha']);
function exactKeys(value) {
  const keys = Object.keys(value).sort();
  return keys.length === EXPECTED_KEYS.length && keys.every((k,i) => k === [...EXPECTED_KEYS].sort()[i]);
}
export function validateManifest(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input) || !exactKeys(input)) {
    throw new Error('MANIFEST_FIELDS_INVALID');
  }
  if (input.schema_version !== SCHEMA_VERSION) throw new Error('SCHEMA_VERSION_DENIED');
  if (typeof input.job_id !== 'string' || !/^JSCC-DEV-[A-Z0-9-]{4,48}$/.test(input.job_id)) {
    throw new Error('JOB_ID_INVALID');
  }
  if (input.project !== DEV_PROJECT || input.environment !== 'DEV') throw new Error('DEV_ONLY');
  if (input.baseline_sha !== BASELINE_SHA) throw new Error('BASELINE_UNEXPECTED');
  if (!Object.hasOwn(OPS,input.operation)) throw new Error('OPERATION_DENIED');
  return Object.freeze({
    schema_version: input.schema_version,
    job_id: input.job_id,
    project: DEV_PROJECT,
    environment: 'DEV',
    operation: input.operation,
    baseline_sha: input.baseline_sha,
    task: OPS[input.operation],
    approval_state: 'NO_DEPLOYMENT_AUTHORIZED',
  });
}
export function describeResult(manifest, testSummary) {
  const task=validateManifest(manifest);
  if (!testSummary || typeof testSummary !== 'object' ||
      !Number.isInteger(testSummary.pass) || !Number.isInteger(testSummary.fail) ||
      testSummary.pass < 0 || testSummary.fail < 0 || ![0,1].includes(testSummary.exit_code)) {
    throw new Error('RESULT_INVALID');
  }
  return Object.freeze({
    schema_version: SCHEMA_VERSION,
    job_id:task.job_id,project:DEV_PROJECT,environment:'DEV',operation:task.operation,
    baseline_sha:task.baseline_sha,
    verdict:testSummary.exit_code === 0 && testSummary.fail === 0 && testSummary.pass > 0 ? 'PASS' : 'FAIL',
    tests_pass:testSummary.pass,tests_fail:testSummary.fail,exit_code:testSummary.exit_code,
    deployment_performed:false,
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {validateManifest,describeResult,BASELINE_SHA} from './bridge-contract.mjs';
const good={schema_version:1,job_id:'JSCC-DEV-BRIDGE-0001',project:'jscc-dev',environment:'DEV',operation:'bridge_smoke_test',baseline_sha:BASELINE_SHA};
const reject=(patch,expected)=>assert.throws(()=>validateManifest({...good,...patch}),new RegExp(expected));
test('admit exact DEV smoke-test manifest with fixed argv',()=>{
  const task=validateManifest(good);
  assert.deepEqual(task.task.argv,['--test','drive-bridge/bridge-contract.test.mjs']);
  assert.equal(task.approval_state,'NO_DEPLOYMENT_AUTHORIZED');
});
test('deny TEST or PROD',()=>{reject({environment:'TEST'},'DEV_ONLY');reject({environment:'PROD'},'DEV_ONLY');});
test('deny different GCP project',()=>reject({project:'jscc-prod'},'DEV_ONLY'));
test('deny arbitrary commands and deploy operations',()=>{reject({operation:'shell'},'OPERATION_DENIED');reject({operation:'deploy'},'OPERATION_DENIED');});
test('deny unverified baseline',()=>reject({baseline_sha:'0'.repeat(40)},'BASELINE_UNEXPECTED'));
test('deny caller-supplied command/path/arguments',()=>{
  for(const injected of [{argv:['rm','-rf','/']},{path:'../../.env'},{command:'sh'},{approval:true}]){
    assert.throws(()=>validateManifest({...good,...injected}),/MANIFEST_FIELDS_INVALID/);
  }
});
test('deny malformed input',()=>{
  assert.throws(()=>validateManifest(null),/MANIFEST_FIELDS_INVALID/);
  assert.throws(()=>validateManifest({...good,job_id:'../x'}),/JOB_ID_INVALID/);
  assert.throws(()=>validateManifest({...good,schema_version:2}),/SCHEMA_VERSION_DENIED/);
});
test('result encodes test verdict, never deploy approval',()=>{
  const ok=describeResult(good,{pass:8,fail:0,exit_code:0});
  assert.equal(ok.verdict,'PASS');assert.equal(ok.deployment_performed,false);
  const bad=describeResult(good,{pass:6,fail:2,exit_code:1});
  assert.equal(bad.verdict,'FAIL');
});

// JSCC DEV bridge isolated runner. Fixed test allowlist; never uses GCP credentials.
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
import {resolve} from 'node:path';

const PINNED = Object.freeze({
  'bridge-contract.mjs':'a3b27388ef06cc17bda9276fb5bbc318acea78614b6cd30851624d57a2066e01',
  'bridge-contract.test.mjs':'79a4c6a01323fcfc45a189142f34db7f8a9e7854262adb9f2731a6e10525120f',
});
async function verifyFile(file,expected) {
  const bytes=await readFile(resolve('drive-bridge',file));
  const actual=createHash('sha256').update(bytes).digest('hex');
  if(actual!==expected)throw new Error('DIGEST_MISMATCH:'+file);
}
async function runFixedTest(command) {
  if(command.executable!=='node'||JSON.stringify(command.argv)!==JSON.stringify(['--test','drive-bridge/bridge-contract.test.mjs'])) {
    throw new Error('COMMAND_NOT_APPROVED');
  }
  return await new Promise((resolveRun,reject)=>{
    let stdout='', stderr='', overflow=false, timedOut=false;
    const child=spawn(process.execPath,command.argv,{
      cwd:process.cwd(),
      shell:false,
      stdio:['ignore','pipe','pipe'],
      env:{PATH:process.env.PATH||'/usr/bin:/bin',CI:'true',NODE_ENV:'test'},
    });
    const timer=setTimeout(()=>{timedOut=true;child.kill('SIGKILL')},15000);
    child.stdout.on('data',buf=>{if(stdout.length+buf.length>32000){overflow=true;child.kill('SIGKILL');}else stdout+=buf.toString('utf8')});
    child.stderr.on('data',buf=>{if(stderr.length+buf.length>32000){overflow=true;child.kill('SIGKILL');}else stderr+=buf.toString('utf8')});
    child.on('error',err=>{clearTimeout(timer);reject(err)});
    child.on('close',(exit_code)=>{clearTimeout(timer);
      if(overflow||timedOut) return reject(new Error(overflow?'OUTPUT_LIMIT':'TIMEOUT'));
      const parse=field=>{const match=stdout.match(new RegExp('^# '+field+'\\s+(\\d+)','m'));return match?Number(match[1]):null};
      resolveRun({exit_code,pass:parse('pass'),fail:parse('fail'),tests:parse('tests'),stderr_present:!!stderr});
    });
  });
}
async function main(){
  for(const [file,digest] of Object.entries(PINNED))await verifyFile(file,digest);
  const {validateManifest,describeResult}=await import('./bridge-contract.mjs');
  const manifest=JSON.parse(await readFile(resolve('drive-bridge','bridge-request.json'),'utf8'));
  const task=validateManifest(manifest);
  const run=await runFixedTest(task.task);
  if(run.pass===null||run.fail===null||run.tests===null)throw Error('TAP_SUMMARY_MISSING');
  const result=describeResult(manifest,{pass:run.pass,fail:run.fail,exit_code:run.exit_code===0?0:1});
  console.log(JSON.stringify({...result, tests_total:run.tests,
    script_sha256:PINNED['bridge-contract.mjs'],
    test_sha256:PINNED['bridge-contract.test.mjs'],
    source_baseline_verified:false,
    executor_mode:'sandbox_only',
    time_utc:new Date().toISOString()}));
  process.exitCode=result.verdict==='PASS'?0:1;
}
main().catch(e=>{console.log(JSON.stringify({verdict:'ERROR',error_code:String(e.message).slice(0,100),deployment_performed:false}));process.exitCode=1});
